        SparseGradient out = a1.multiply(b1).add(a2.multiply(b2));

        // recompute an accurate value, taking care of cancellations
        out.value = Sum.create()
            .addProduct(a1.value, b1.value)
            .addProduct(a2.value, b2.value).getAsDouble();

        return out;
    }

