    @Override
    public int indexOf(@Nullable Object o) {
      refreshIfEmpty();
      return getListDelegate().indexOf(o);
    }

    @Override
    public int lastIndexOf(@Nullable Object o) {
      refreshIfEmpty();
      return getListDelegate().lastIndexOf(o);
    }

